describe('Dynamic Loading - Async Wait', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  it('should reveal hidden content after asynchronous load', () => {
    // Verify initial state
    cy.get('[data-testid="finish-button"]').should('be.visible');
    cy.get('[data-testid="finish-button"]').should('not.contain', 'Hello World!');
    cy.get('[data-testid="loading-indicator"]').should('not.exist');

    // Click the start button to initiate async load
    cy.get('[data-testid="start-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-indicator"]').should('be.visible');
    cy.get('[data-testid="loading-indicator"]').should('contain', 'Loading...');

    // Wait for the async operation to complete (up to 10 seconds)
    cy.get('[data-testid="loading-indicator"]').should('not.exist', { timeout: 10000 });

    // Verify hidden content is now visible
    cy.get('[data-testid="finish-button"]').should('be.visible');
    cy.get('[data-testid="finish-button"]').should('contain', 'Hello World!');

    // Verify the loading indicator is gone
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
  });

  it('should handle timeout when async operation fails to complete', () => {
    // Intercept the API call and delay it beyond the timeout
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000);
        res.send({ statusCode: 200, body: { data: 'Hello World!' } });
      });
    }).as('delayedLoad');

    // Click the start button
    cy.get('[data-testid="start-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Wait for the timeout to occur
    cy.wait('@delayedLoad', { timeout: 10000 });

    // Verify the loading indicator is still visible (timeout occurred)
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Verify finish button is NOT visible
    cy.get('[data-testid="finish-button"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Request timed out');
  });
});
